<script setup lang="ts">
import type { Version } from '../../types'
import { shortId, dateTime } from '../../utils/display'
import StatusBadge from '../shared/StatusBadge.vue'
defineProps<{ version: Version; maker: boolean; busy: boolean; dirty: boolean }>()
const emit = defineEmits<{ freeze: []; prepare: [] }>()
</script>
<template><aside class="panel stack"><h2>门禁与冻结</h2><StatusBadge :status="version.status" /><p class="small muted">冻结后，配置和质量规则将被锁定。</p><div v-for="check in version.gate_report?.checks ?? []" :key="check.name" class="stack-sm"><div class="inline spread"><strong class="small">{{ check.name }}</strong><span class="badge">{{ check.status === 'passed' ? '已通过' : check.status === 'skipped' ? '已跳过' : '未通过' }}</span></div><p class="small muted">{{ check.message }}</p></div><p v-if="!version.gate_report" class="small muted">配置语法、算子在册和 Schema 对齐将在冻结时统一检查。</p><hr class="divider" /><dl class="kv-list"><div class="kv"><dt>来源快照</dt><dd class="mono">{{ shortId(version.source_profile_id) }}</dd></div><div class="kv"><dt>目标快照</dt><dd class="mono">{{ shortId(version.target_profile_id) }}</dd></div><div class="kv"><dt>冻结时间</dt><dd>{{ dateTime(version.frozen_at) }}</dd></div></dl><div><p class="small muted">版本指纹</p><p class="mono">{{ version.sha256 || '通过门禁并冻结后生成' }}</p></div><button v-if="maker && version.status === 'draft'" class="btn btn-primary" :disabled="busy || dirty" @click="emit('freeze')">执行门禁并冻结</button><p v-if="dirty" class="small muted">请先保存质量规则，再冻结版本。</p><button v-if="maker" class="btn" :disabled="busy || version.status !== 'frozen'" @click="emit('prepare')">生成准备单</button><p class="small muted">准备单只描述影响范围与预算，不会启动数据作业。</p><RouterLink v-if="version.status === 'rejected'" to="/studio" class="text-button">调整需求并重新生成方案</RouterLink></aside></template>
